UPDATE lineitem SET l_extendedprice = l_extendedprice + 25.37, l_discount = 0.06 WHERE (l_orderkey, l_linenumber) IN (SELECT DISTINCT l.l_orderkey, l.l_linenumber FROM lineitem l JOIN part p ON p.p_partkey = l.l_partkey JOIN partsupp ps ON ps.ps_partkey = l.l_partkey AND ps.ps_suppkey = l.l_suppkey JOIN supplier s ON s.s_suppkey = l.l_suppkey JOIN nation n ON n.n_nationkey = s.s_nationkey JOIN orders o ON o.o_orderkey = l.l_orderkey WHERE p.p_name LIKE '%green%' ORDER BY l.l_orderkey, l.l_linenumber LIMIT 24);
